        self.val = val
        self.left = left
        self.right = right


def tree_to_level_order(root):
    if root is None:
        return []
    result = []
    queue = [root]
    while queue:
        node = queue.pop(0)
        if node is None:
            result.append(None)
            continue
        result.append(node.val)
        queue.append(node.left)
        queue.append(node.right)
    while result and result[-1] is None:
        result.pop()
    return result


def bst_from_preorder(preorder):
    idx = [0]

    def build(bound):
        if idx[0] == len(preorder) or preorder[idx[0]] > bound:
            return None
        val = preorder[idx[0]]
        idx[0] += 1
        node = TreeNode(val)
        node.left = build(val)
        node.right = build(bound)
        return node

    root = build(float('inf'))
    return tree_to_level_order(root)

